INSERT INTO public.dua_library (id, category, occasion, title, arabic_text, turkish_meaning, source_citation, source_url, context_note)
VALUES
  ('q-2-201', 'quran', 'Günlük', 'Dünya ve âhiret iyiliği', 'رَبَّنَآ اٰتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْاٰخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', 'Rabbimiz! Bize dünyada iyilik, âhirette de iyilik ver; bizi ateş azabından koru.', 'Bakara 2:201', 'https://quran.com/2/201', 'Dünya ile âhiret dengesini isteyen kapsamlı bir Kur’an duası.'),
  ('q-2-250', 'quran', 'Sıkıntı', 'Sabır ve sebat', 'رَبَّنَآ اَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ اَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِر۪ينَ', 'Rabbimiz! Üzerimize sabır yağdır, ayaklarımızı sağlam tut ve inkârcı topluma karşı bize yardım et.', 'Bakara 2:250', 'https://quran.com/2/250', 'Zorluk karşısında sabır, sağlam duruş ve yardım talebi.'),
  ('q-2-286', 'quran', 'Sıkıntı', 'Gücümüzün yetmediği yüklerden korunma', 'رَبَّنَا لَا تُؤَاخِذْنَٓا اِنْ نَس۪ينَٓا اَوْ اَخْطَأْنَاۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَٓا اِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذ۪ينَ مِنْ قَبْلِنَاۚ', 'Rabbimiz! Unutur veya yanılırsak bizi sorumlu tutma; bizden öncekilere yüklediğin gibi bize de ağır yük yükleme.', 'Bakara 2:286', 'https://quran.com/2/286', 'Hata, unutma ve ağır sorumluluk karşısında Allah’a sığınma.'),
  ('q-3-8', 'quran', 'İman', 'Kalbin doğrulukta kalması', 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ اِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةًۚ اِنَّكَ اَنْتَ الْوَهَّابُ', 'Rabbimiz! Bizi doğru yola ilettikten sonra kalplerimizi eğriltme; bize katından rahmet bağışla. Şüphesiz çok bağışlayan sensin.', 'Âl-i İmrân 3:8', 'https://quran.com/3/8', 'Hidayette sebat ve rahmet için okunur.'),
  ('q-3-16', 'quran', 'Tövbe', 'Bağışlanma ve korunma', 'رَبَّنَٓا اِنَّنَٓا اٰمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ', 'Rabbimiz! Biz iman ettik; günahlarımızı bağışla, bizi ateş azabından koru.', 'Âl-i İmrân 3:16', 'https://quran.com/3/16', 'İman ikrarıyla birlikte bağışlanma dileği.'),
  ('q-3-147', 'quran', 'Sıkıntı', 'Hataları bağışlama ve sebat', 'رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَاِسْرَافَنَا ف۪ٓي اَمْرِنَا وَثَبِّتْ اَقْدَامَنَا', 'Rabbimiz! Günahlarımızı ve işlerimizdeki taşkınlığımızı bağışla, ayaklarımızı sağlam tut.', 'Âl-i İmrân 3:147', 'https://quran.com/3/147', 'Hata sonrası toparlanma ve kararlılık talebi.'),
  ('q-3-191', 'quran', 'İman', 'Yaratılış üzerine tefekkür', 'رَبَّنَا مَا خَلَقْتَ هٰذَا بَاطِلًاۚ سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ', 'Rabbimiz! Sen bunu boş yere yaratmadın. Seni tenzih ederiz; bizi ateş azabından koru.', 'Âl-i İmrân 3:191', 'https://quran.com/3/191', 'Göklerin ve yerin yaratılışı üzerinde tefekkür ederken.'),
  ('q-7-23', 'quran', 'Tövbe', 'Âdem ve Havvâ’nın tövbesi', 'رَبَّنَا ظَلَمْنَٓا اَنْفُسَنَا وَاِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِر۪ينَ', 'Rabbimiz! Biz kendimize zulmettik. Eğer bizi bağışlamaz ve bize acımazsan mutlaka ziyan edenlerden oluruz.', 'A‘râf 7:23', 'https://quran.com/7/23', 'Yanlışı kabul ederek samimi tövbe etmek için.'),
  ('q-10-85', 'quran', 'Sıkıntı', 'Zulme araç olmaktan korunma', 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِلْقَوْمِ الظَّالِم۪ينَۙ وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِر۪ينَ', 'Rabbimiz! Bizi zalimler topluluğu için deneme konusu kılma; rahmetinle bizi inkârcılardan kurtar.', 'Yûnus 10:85-86', 'https://quran.com/10/85', 'Baskı ve zulüm karşısında korunma dileği.'),
  ('q-11-47', 'quran', 'Tövbe', 'Bilgisizce istemekten korunma', 'رَبِّ اِنّ۪ٓي اَعُوذُ بِكَ اَنْ اَسْـَٔلَكَ مَا لَيْسَ ل۪ي بِه۪ عِلْمٌۜ وَاِلَّا تَغْفِرْ ل۪ي وَتَرْحَمْن۪ٓي اَكُنْ مِنَ الْخَاسِر۪ينَ', 'Rabbim! Hakkında bilgim olmayan şeyi istemekten sana sığınırım. Beni bağışlamaz ve bana merhamet etmezsen ziyana uğrayanlardan olurum.', 'Hûd 11:47', 'https://quran.com/11/47', 'Bilginin sınırını kabul edip Allah’a sığınma.'),
  ('q-12-101', 'quran', 'İman', 'Müslüman olarak yaşamak', 'تَوَفَّن۪ي مُسْلِمًا وَاَلْحِقْن۪ي بِالصَّالِح۪ينَ', 'Canımı Müslüman olarak al ve beni iyilere kat.', 'Yûsuf 12:101', 'https://quran.com/12/101', 'Hz. Yûsuf’un iman ve salihlerle beraberlik duası.'),
  ('q-14-40', 'quran', 'Aile', 'Namazı devamlı kılmak', 'رَبِّ اجْعَلْن۪ي مُق۪يمَ الصَّلٰوةِ وَمِنْ ذُرِّيَّت۪يۗ رَبَّنَا وَتَقَبَّلْ دُعَٓاءِ', 'Rabbim! Beni ve soyumdan gelecekleri namazı devamlı kılanlardan eyle; Rabbimiz, duamı kabul et.', 'İbrâhîm 14:40', 'https://quran.com/14/40', 'Kişinin kendisi ve ailesi için ibadette devamlılık dileği.'),
  ('q-17-24', 'quran', 'Aile', 'Anne babaya rahmet', 'رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَان۪ي صَغ۪يرًا', 'Rabbim! Küçüklüğümde onlar beni nasıl yetiştirmişlerse şimdi de sen onlara merhamet et.', 'İsrâ 17:24', 'https://quran.com/17/24', 'Anne baba için rahmet duası.'),
  ('q-18-10', 'quran', 'Sıkıntı', 'Doğru bir çıkış yolu', 'رَبَّنَٓا اٰتِنَا مِنْ لَدُنْكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ اَمْرِنَا رَشَدًا', 'Rabbimiz! Bize katından rahmet ver ve işimizde bize doğruyu göster, bizi başarıya ulaştır.', 'Kehf 18:10', 'https://quran.com/18/10', 'Zor bir kararda rahmet ve doğru yol istemek için.'),
  ('q-20-25', 'quran', 'İlim', 'Göğsün genişlemesi ve anlatım kolaylığı', 'رَبِّ اشْرَحْ ل۪ي صَدْر۪يۙ وَيَسِّرْ ل۪ٓي اَمْر۪يۙ وَاحْلُلْ عُقْدَةً مِنْ لِسَان۪يۙ يَفْقَهُوا قَوْل۪ي', 'Rabbim! Gönlüme ferahlık ver. İşimi bana kolaylaştır. Dilimdeki tutukluğu çöz ki sözümü anlasınlar.', 'Tâhâ 20:25-28', 'https://quran.com/20/25', 'Konuşma, sınav, sunum ve sorumluluk öncesinde okunabilir.'),
  ('q-21-83', 'quran', 'Sağlık', 'Hz. Eyyûb’un sıkıntı duası', 'اَنّ۪ي مَسَّنِيَ الضُّرُّ وَاَنْتَ اَرْحَمُ الرَّاحِم۪ينَ', 'Başıma bu dert geldi. Ama sen merhametlilerin en üstünüsün.', 'Enbiyâ 21:83', 'https://quran.com/21/83', 'Hastalık ve uzun süren sıkıntı zamanında.'),
  ('q-21-87', 'quran', 'Tövbe', 'Hz. Yûnus’un duası', 'لَٓا اِلٰهَ اِلَّٓا اَنْتَ سُبْحَانَكَۗ اِنّ۪ي كُنْتُ مِنَ الظَّالِم۪ينَ', 'Senden başka ilâh yoktur. Seni tenzih ederim. Gerçekten ben zalimlerden oldum.', 'Enbiyâ 21:87', 'https://quran.com/21/87', 'Sıkışmışlık içinde tevhid, tesbih ve hatayı kabul etme duası.'),
  ('q-23-29', 'quran', 'Yolculuk', 'Bereketli bir yere varmak', 'رَبِّ اَنْزِلْن۪ي مُنْزَلًا مُبَارَكًا وَاَنْتَ خَيْرُ الْمُنْزِل۪ينَ', 'Rabbim! Beni bereketli bir yere indir. Sen konuklayanların en hayırlısısın.', 'Mü’minûn 23:29', 'https://quran.com/23/29', 'Yeni bir yere varırken veya yeni bir başlangıçta.'),
  ('q-25-74', 'quran', 'Aile', 'Göz aydınlığı bir aile', 'رَبَّنَا هَبْ لَنَا مِنْ اَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ اَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّق۪ينَ اِمَامًا', 'Rabbimiz! Eşlerimizi ve çocuklarımızı bize göz aydınlığı kıl ve bizi Allah’a karşı gelmekten sakınanlara önder eyle.', 'Furkân 25:74', 'https://quran.com/25/74', 'Aile huzuru ve güzel örneklik için.'),
  ('q-59-10', 'quran', 'İman', 'Müminlere karşı kalbi arındırmak', 'رَبَّنَا اغْفِرْ لَنَا وَلِاِخْوَانِنَا الَّذ۪ينَ سَبَقُونَا بِالْا۪يمَانِ وَلَا تَجْعَلْ ف۪ي قُلُوبِنَا غِلًّا لِلَّذ۪ينَ اٰمَنُوا', 'Rabbimiz! Bizi ve bizden önce iman etmiş kardeşlerimizi bağışla; kalplerimizde iman edenlere karşı kin bırakma.', 'Haşr 59:10', 'https://quran.com/59/10', 'Bağışlama, kardeşlik ve kalp temizliği için.'),
  ('h-muslim-2721', 'hadith', 'Günlük', 'Hidayet, takvâ, iffet ve gönül zenginliği', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى', 'Allah’ım! Senden hidayet, takvâ, iffet ve gönül zenginliği isterim.', 'Sahih Müslim 2721a', 'https://sunnah.com/muslim:2721a', 'Resûlullah’ın kapsamlı ve kısa dualarından.'),
  ('h-bukhari-6369', 'hadith', 'Sıkıntı', 'Kaygı, üzüntü ve borç yükünden korunma', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ', 'Allah’ım! Kaygıdan, üzüntüden, acizlikten, tembellikten, korkaklıktan, cimrilikten, borç yükünden ve insanların baskısından sana sığınırım.', 'Sahih el-Buhârî 6369', 'https://sunnah.com/bukhari:6369', 'Kaygı, yetersizlik hissi ve borç baskısı karşısında.'),
  ('h-bukhari-5743', 'hadith', 'Sağlık', 'Şifa duası', 'اللَّهُمَّ رَبَّ النَّاسِ أَذْهِبِ الْبَأْسَ، اشْفِ أَنْتَ الشَّافِي، لاَ شِفَاءَ إِلاَّ شِفَاؤُكَ، شِفَاءً لاَ يُغَادِرُ سَقَمًا', 'Ey insanların Rabbi! Sıkıntıyı gider, şifa ver; şifa veren sensin. Senin şifandan başka şifa yoktur. Hastalık bırakmayan bir şifa ver.', 'Sahih el-Buhârî 5743', 'https://sunnah.com/bukhari:5743', 'Hasta için Resûlullah’ın okuduğu şifa duası.'),
  ('h-bukhari-6306', 'hadith', 'Tövbe', 'Seyyidü’l-istiğfar', 'اللَّهُمَّ أَنْتَ رَبِّي لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ', 'Allah’ım! Sen benim Rabbimsin, senden başka ilâh yoktur. Beni sen yarattın, ben senin kulunum; gücüm yettiğince ahdin ve vaadin üzereyim.', 'Sahih el-Buhârî 6306', 'https://sunnah.com/bukhari:6306', 'Hadiste “istiğfarın en üstünü” diye tanıtılan duanın başlangıcıdır; kaynak bağlantısında tam metin yer alır.'),
  ('h-muslim-2722', 'hadith', 'İlim', 'Faydasız bilgiden korunma', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لاَ يَنْفَعُ وَمِنْ قَلْبٍ لاَ يَخْشَعُ وَمِنْ نَفْسٍ لاَ تَشْبَعُ وَمِنْ دَعْوَةٍ لاَ يُسْتَجَابُ لَهَا', 'Allah’ım! Fayda vermeyen bilgiden, ürpermeyen kalpten, doymayan nefisten ve kabul edilmeyen duadan sana sığınırım.', 'Sahih Müslim 2722', 'https://sunnah.com/muslim:2722', 'Bilginin faydaya, kalbin huşûa dönüşmesi için.'),
  ('h-bukhari-6324', 'hadith', 'Günlük', 'Uyurken', 'بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا', 'Allah’ım! Senin adınla ölür ve dirilirim.', 'Sahih el-Buhârî 6324', 'https://sunnah.com/bukhari:6324', 'Yatağa girerken okunan kısa dua.'),
  ('h-bukhari-6312', 'hadith', 'Günlük', 'Uyanınca', 'الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ', 'Bizi öldürdükten sonra dirilten Allah’a hamdolsun. Dönüş yalnız O’nadır.', 'Sahih el-Buhârî 6312', 'https://sunnah.com/bukhari:6312', 'Uykudan uyanınca okunan dua.'),
  ('h-bukhari-6320', 'hadith', 'Günlük', 'Yatağa girerken korunma', 'بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ، إِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا', 'Rabbim! Senin adınla yanımı yatağa koydum, senin yardımınla kaldırırım. Canımı alırsan ona merhamet et; geri verirsen salih kullarını koruduğun gibi onu koru.', 'Sahih el-Buhârî 6320', 'https://sunnah.com/bukhari:6320', 'Uyumadan önce korunma ve teslimiyet duası.'),
  ('h-abudawud-5095', 'hadith', 'Günlük', 'Evden çıkarken', 'بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ، لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ', 'Allah’ın adıyla; Allah’a tevekkül ettim. Güç ve kuvvet ancak Allah’ın yardımıyladır.', 'Sünen Ebû Dâvûd 5095', 'https://sunnah.com/abudawud:5095', 'Evden çıkarken tevekkül için.'),
  ('h-muslim-1342', 'hadith', 'Yolculuk', 'Yolculuk duası', 'سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ', 'Bunu hizmetimize veren Allah’ı tenzih ederiz; yoksa bizim buna gücümüz yetmezdi. Şüphesiz Rabbimize döneceğiz.', 'Sahih Müslim 1342', 'https://sunnah.com/muslim:1342', 'Bir yolculuğa ve bineğe başlarken okunan duanın başlangıcı.'),
  ('h-muslim-713', 'hadith', 'İbadet', 'Mescide girerken', 'اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ', 'Allah’ım! Bana rahmetinin kapılarını aç.', 'Sahih Müslim 713a', 'https://sunnah.com/muslim:713a', 'Mescide girerken okunur.'),
  ('h-muslim-713-exit', 'hadith', 'İbadet', 'Mescidden çıkarken', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ', 'Allah’ım! Senin lütfundan isterim.', 'Sahih Müslim 713b', 'https://sunnah.com/muslim:713b', 'Mescidden çıkarken okunur.'),
  ('h-tirmidhi-2140', 'hadith', 'İman', 'Kalbin dinde sabit kalması', 'يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ', 'Ey kalpleri çeviren! Kalbimi dinin üzere sabit kıl.', 'Câmi‘ et-Tirmizî 2140 (hasen)', 'https://sunnah.com/tirmidhi:2140', 'Resûlullah’ın sıkça yaptığı dualardan.'),
  ('h-abudawud-5074', 'hadith', 'Sağlık', 'Af ve âfiyet', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ', 'Allah’ım! Senden dünyada ve âhirette af ve âfiyet isterim.', 'Sünen Ebû Dâvûd 5074', 'https://sunnah.com/abudawud:5074', 'Sabah ve akşam okunması tavsiye edilen kapsamlı dua.'),
  ('h-ibnmajah-925', 'hadith', 'İlim', 'Faydalı ilim ve temiz rızık', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلاً مُتَقَبَّلاً', 'Allah’ım! Senden faydalı ilim, temiz rızık ve kabul edilmiş amel isterim.', 'Sünen İbn Mâce 925', 'https://sunnah.com/ibnmajah:925', 'Sabah namazından sonra rivayet edilen dua.'),
  ('h-abudawud-1516', 'hadith', 'Tövbe', 'Tövbe ve bağışlanma', 'رَبِّ اغْفِرْ لِي وَتُبْ عَلَىَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ', 'Rabbim! Beni bağışla, tövbemi kabul et. Şüphesiz sen tövbeleri çok kabul eden ve çok merhametli olansın.', 'Sünen Ebû Dâvûd 1516', 'https://sunnah.com/abudawud:1516', 'Resûlullah’ın bir mecliste çokça tekrar ettiği rivayet edilen istiğfar.'),
  ('s-bukhari-834', 'companions', 'Tövbe', 'Hz. Ebû Bekir’e öğretilen bağışlanma duası', 'اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي', 'Allah’ım! Ben kendime çok zulmettim. Günahları ancak sen bağışlarsın. Katından bir bağışlamayla beni bağışla ve bana merhamet et.', 'Sahih el-Buhârî 834', 'https://sunnah.com/bukhari:834', 'Hz. Ebû Bekir’in namazında okuyabilmek için Resûlullah’tan istediği dua.'),
  ('s-abudawud-1522', 'companions', 'İbadet', 'Muâz b. Cebel’e öğretilen dua', 'اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ', 'Allah’ım! Seni anmak, sana şükretmek ve sana güzelce ibadet etmek için bana yardım et.', 'Sünen Ebû Dâvûd 1522 (sahih)', 'https://sunnah.com/abudawud:1522', 'Resûlullah’ın Muâz’a her namazın sonunda bırakmamasını öğütlediği dua.'),
  ('s-muslim-2725', 'companions', 'İlim', 'Hz. Ali’ye öğretilen doğruluk duası', 'اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي', 'Allah’ım! Bana hidayet ver ve beni doğruya isabet ettir.', 'Sahih Müslim 2725a', 'https://sunnah.com/muslim:2725a', 'Resûlullah’ın Hz. Ali’ye öğrettiği kısa ve kapsamlı dua.'),
  ('s-muslim-918', 'companions', 'Sıkıntı', 'Ümmü Seleme’ye öğretilen musibet duası', 'اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا', 'Allah’ım! Musibetimde bana ecir ver ve onun yerine daha hayırlısını lütfet.', 'Sahih Müslim 918b', 'https://sunnah.com/muslim:918b', 'Ümmü Seleme’nin aktardığı, musibet anında söylenen dua.')
